INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.49.1',
  '2026-07-28',
  'AI — фикс доставки результата прогона после переподключения агента',
  'Исправлено: задача на странице AI могла навсегда зависнуть в статусе «выполняется», если во время её выполнения обрывалась связь агента с сервером (например, задача сама деплоила релиз и перезапускала сервер). Теперь результат доставляется после переподключения автоматически.',
  E'Баг: горутина прогона в habits-ai-agent держала ссылку на соединение времени своего старта; после reconnect отправка run_result шла в закрытый сокет («use of closed network connection»), результат попадал в очередь повтора, но повтор выполнялся только в момент следующего подключения — при стабильном новом соединении результат застревал в памяти агента навсегда (прогон в БД оставался running до 2ч-реапера). Фикс (agent v1.0.1): глобальный указатель текущего соединения (sendCurrent) для run_status/run_result + периодический flusher (30с), дошлющий неподтверждённые (без run_ack) результаты — сервер идемпотентен, повтор безопасен. Регрессионный тест: рестарт сервера посреди прогона → результат доставлен после reconnect. Застрявший прод-результат спасён передёргиванием WS (restart app) до обновления агента (результат жил в памяти процесса). Бинарники ai-v1.0.1 в habits-agent (в latest — бинарники всех агентов).'
);
